 import unittest
from candidate import strange_sort_list

class TestStrangeSortList(unittest.TestCase):
    def test_strange_sort_list_normalcase(self):
        self.assertEqual(strange_sort_list([1, 2, 3, 4]), [1, 4, 2, 3])

    def test_strange_sort_list_increasing(self):
        self.assertEqual(strange_sort_list([1, 2, 3]), [1, 3, 2])

    def test_strange_sort_list_decreasing(self):
        self.assertEqual(strange_sort_list([4, 3, 2]), [4, 2, 3])

    def test_strange_sort_list_single_element(self):
        self.assertEqual(strange_sort_list([5]), [5])

    def test_strange_sort_list_duplicate_min(self):
        self.assertEqual(strange_sort_list([1, 1, 2, 3]), [1, 3, 1, 2])

    def test_strange_sort_list_duplicate_max(self):
        self.assertEqual(strange_sort_list([2, 2, 3, 4]), [2, 4, 2, 3])

    def test_strange_sort_list_empty(self):
        self.assertEqual(strange_sort_list([]), [])

    def test_strange_sort_list_none(self):
        self.assertEqual(strange_sort_list(None), [])

    def test_strange_sort_list_string(self):
        with self.assertRaises(TypeError):
            strange_sort_list('str')

    def test_strange_sort_list_float(self):
        with self.assertRaises(TypeError):
            strange_sort_list([1.1, 2.2, 3.3])

if __name__ == '__main__':
    unittest.main()
